This NestJS service method has deeply nested conditionals. Refactor using early returns:
```typescript
@Injectable()
export class OrderService {
  async processOrder(orderId: number, userId: number): Promise<Order> {
    const order = await this.orderRepo.findById(orderId);
    if (order) {
      if (order.status === 'pending') {
        const user = await this.userRepo.findById(userId);
        if (user) {
          if (user.hasPermission('process_orders')) {
            if (order.total > 0) {
              order.status = 'processed';
              return this.orderRepo.save(order);
            } else {
              throw new BadRequestException('Invalid total');
            }
          } else {
            throw new ForbiddenException('No permission');
          }
        } else {
          throw new NotFoundException('User not found');
        }
      } else {
        throw new BadRequestException('Order is not pending');
      }
    } else {
      throw new NotFoundException('Order not found');
    }
  }
}
```

